def course(tid, title, subtitle, concepts, method, method_body,
           example_stem, example_steps, example_answer,
           pit_title, pit_wrong, pit_why, pit_correct, pit_tag,
           check_stem, check_choices, check_answer, check_explain,
           prereq=None, nxt=None):
    return lesson(tid, title, subtitle,
        objectives=["อธิบายหลักการสำคัญของหัวข้อนี้ได้", "เลือกสูตรและหน่วยให้ตรงกับสิ่งที่ถาม", "ตรวจลำดับขนาดและความสมเหตุสมผลของคำตอบได้"],
        minutes=30, prereq=prereq or [], nxt=nxt or [],
        blocks=[
            hook(subtitle),
            concept("แนวคิดหลัก", concepts),
            technique(method, "เมื่อโจทย์มีหลายค่า หลายหน่วย หรือหลายขั้น", "อย่ารีบแทนสูตรก่อนระบุสิ่งที่โจทย์ถาม", method_body, tip=method),
            example("ตัวอย่าง", example_stem, example_steps, example_answer),
            pitfall(pit_title, pit_wrong, pit_why, pit_correct, pit_tag),
            *review_blocks(tid),
            summary("ระบุปริมาณที่ถามและหน่วย", "เลือกความสัมพันธ์ที่ตรงกับสถานการณ์", "คำนวณทีละขั้น", "ตรวจหน่วย ทิศทาง และลำดับขนาด"),
            check(check_stem, check_choices, check_answer, check_explain),
        ], patterns=[method, pit_title], sources=SRC)


def N(stem, ans, wrong, steps, hints, explain, diff=3, sec=120, tags=None):
    return q(stem, ans, wrong, steps, hints, explain,
             diff=diff, sec=sec, reading="high" if diff >= 4 else "medium", tags=tags)


def balance_new(items, difficulties, start=None):
    """ปรับเฉพาะข้อใหม่จากรอบก่อนให้เติมระดับที่ขาด โดยไม่แตะระดับของข้อเดิม."""
    start = len(items) - len(difficulties) if start is None else start
    if start >= 0 and len(items) >= start + len(difficulties):
        time_caps = {1: 55, 2: 90, 3: 120, 4: 140, 5: 150}
        for item, difficulty in zip(items[start:start + len(difficulties)], difficulties):
            item["diff"] = difficulty
            item["sec"] = min(item["sec"], time_caps[difficulty])
            item["reading"] = "low" if difficulty <= 2 else ("medium" if difficulty == 3 else "high")
    return items


